  1→import { useState, useEffect, useRef, type ReactNode } from 'react';
  2→import type { SearchResult } from '../../services/search-index.service';
  3→import '../../styles/search-palette.css';
  4→
  5→// ---------------------------------------------------------------------------
  6→// Helper functions
  7→// ---------------------------------------------------------------------------
  8→
  9→/**
 10→ * Return a terminal-aesthetic icon for a file or folder.
 11→ * Uses Unicode characters that render well in JetBrains Mono.
 12→ */
 13→function getFileIcon(name: string, type: 'file' | 'folder'): string {
 14→  if (type === 'folder') return '\u{1F5C0}'; // folder icon
 15→
 16→  const lower = name.toLowerCase();
 17→  const lastDot = lower.lastIndexOf('.');
 18→  if (lastDot === -1) return '\u{1F5CE}'; // generic file
 19→
 20→  const ext = lower.slice(lastDot);
 21→
 22→  // Image
 23→  if (['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.bmp', '.ico', '.avif'].includes(ext)) {
 24→    return '\u{1F5BC}'; // framed picture
 25→  }
 26→  // Video
 27→  if (['.mp4', '.webm', '.mov', '.mkv'].includes(ext)) {
 28→    return '\u{1F3AC}'; // clapper board
 29→  }
 30→  // Audio
 31→  if (['.mp3', '.wav', '.ogg', '.m4a', '.flac'].includes(ext)) {
 32→    return '\u{266B}'; // beamed eighth notes
 33→  }
 34→  // Document / PDF
 35→  if (ext === '.pdf') {
 36→    return '\u{1F4C4}'; // page facing up
 37→  }
 38→  // Code / text
 39→  if (
 40→    [
 41→      '.ts',
 42→      '.tsx',
 43→      '.js',
 44→      '.jsx',
 45→      '.py',
 46→      '.rs',
 47→      '.go',
 48→      '.java',
 49→      '.c',
 50→      '.cpp',
 51→      '.h',
 52→      '.html',
 53→      '.css',
 54→      '.json',
 55→      '.yaml',
 56→      '.yml',
 57→      '.xml',
 58→      '.toml',
 59→      '.sh',
 60→      '.md',
 61→      '.txt',
 62→    ].includes(ext)
 63→  ) {
 64→    return '\u{1F4DD}'; // memo
 65→  }
 66→
 67→  return '\u{1F5CE}'; // generic file
 68→}
