  1→import { useState, useCallback, useEffect, useRef } from 'react';
  2→import { useFolderStore } from '../stores/folder.store';
  3→import { useAuthStore } from '../stores/auth.store';
  4→import { searchIndexService, type SearchResult } from '../services/search-index.service';
  5→
  6→// ---------------------------------------------------------------------------
  7→// Module-level callback for triggering index rebuild from outside React tree
  8→// ---------------------------------------------------------------------------
  9→
 10→let _rebuildCallback: (() => void) | null = null;
 11→
 12→export function registerRebuildCallback(cb: () => void): void {
 13→  _rebuildCallback = cb;
 14→}
 15→
 16→export function triggerSearchIndexRebuild(): void {
 17→  _rebuildCallback?.();
 18→}
 19→
 20→// ---------------------------------------------------------------------------
 21→// useSearch hook
 22→// ---------------------------------------------------------------------------
 23→
 24→/**
 25→ * React hook bridging SearchIndexService with UI state.
 26→ *
 27→ * Manages the search lifecycle: opening/closing the palette, building/loading
 28→ * the index, querying with debounce, and persisting encrypted state.
 29→ *
 30→ * Global keyboard shortcut Cmd/Ctrl+K toggles the palette.
 31→ * Index auto-clears on logout via auth state watcher.
 32→ */
 33→export function useSearch() {
 34→  // State
 35→  const [isOpen, setIsOpen] = useState(false);
 36→  const [query, setQuery] = useState('');
 37→  const [results, setResults] = useState<SearchResult[]>([]);
 38→  const [isIndexReady, setIsIndexReady] = useState(false);
 39→  const [isBuilding, setIsBuilding] = useState(false);
 40→
 41→  // Refs
 42→  const hasLoadedFromDb = useRef(false);
 43→
 44→  // Store access
 45→  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
 46→  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
 47→  const prevAuth = useRef(isAuthenticated);
 48→
 49→  // Open the palette
 50→  const open = useCallback(() => setIsOpen(true), []);
 51→  const close = useCallback(() => {
 52→    setIsOpen(false);
 53→    setQuery('');
 54→    setResults([]);
 55→  }, []);
 56→  const toggle = useCallback(() => {
 57→    setIsOpen((prev) => {
 58→      if (prev) {
 59→        setQuery('');
 60→        setResults([]);
 61→      }
 62→      return !prev;
 63→    });
 64→  }, []);
 65→
 66→  // Global keyboard shortcut: Cmd/Ctrl+K
 67→  useEffect(() => {
 68→    const handler = (e: KeyboardEvent) => {
 69→      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
 70→        e.preventDefault();
 71→        toggle();
 72→      }
 73→    };
 74→    window.addEventListener('keydown', handler);
 75→    return () => window.removeEventListener('keydown', handler);
 76→  }, [toggle]);
 77→
 78→  // Build/load index when palette opens for the first time
 79→  useEffect(() => {
 80→    if (!isOpen || isIndexReady || isBuilding) return;
 81→    if (!vaultKeypair) return;
 82→
 83→    const init = async () => {
 84→      setIsBuilding(true);
 85→      try {
 86→        // Try loading from encrypted IndexedDB first
 87→        if (!hasLoadedFromDb.current) {
 88→          const loaded = await searchIndexService.loadEncrypted(vaultKeypair.privateKey);
 89→          hasLoadedFromDb.current = true;
 90→          if (loaded && !searchIndexService.isEmpty) {
 91→            setIsIndexReady(true);
 92→            setIsBuilding(false);
 93→            return;
 94→          }
 95→        }
 96→
 97→        // Build fresh from folder store
 98→        const currentFolders = useFolderStore.getState().folders;
 99→        searchIndexService.buildFromFolderTree(currentFolders);
100→        setIsIndexReady(true);
101→
102→        // Persist encrypted (fire-and-forget)
103→        searchIndexService.persistEncrypted(vaultKeypair.privateKey).catch((err) => {
104→          console.warn('[search] Failed to persist index:', err);
105→        });
106→      } catch (err) {
107→        console.error('[search] Failed to initialize index:', err);
108→        // Still mark ready -- search works in-memory even if persistence fails
109→        setIsIndexReady(true);
110→      } finally {
111→        setIsBuilding(false);
112→      }
113→    };
114→    init();
115→  }, [isOpen, isIndexReady, isBuilding, vaultKeypair]);
116→
117→  // Search with debounce (150ms)
118→  useEffect(() => {
119→    if (!isOpen || !isIndexReady) return;
120→    if (!query.trim()) {
121→      setResults([]);
122→      return;
123→    }
124→
125→    const timer = setTimeout(() => {
126→      const searchResults = searchIndexService.search(query.trim());
127→      setResults(searchResults);
128→    }, 150);
129→
130→    return () => clearTimeout(timer);
131→  }, [query, isOpen, isIndexReady]);
132→
133→  // Rebuild index method (called after sync detects changes)
134→  const rebuildIndex = useCallback(() => {
135→    if (!vaultKeypair) return;
136→    const currentFolders = useFolderStore.getState().folders;
137→    searchIndexService.buildFromFolderTree(currentFolders);
138→    setIsIndexReady(true);
139→
140→    // Re-persist (fire-and-forget)
141→    searchIndexService.persistEncrypted(vaultKeypair.privateKey).catch((err) => {
142→      console.warn('[search] Failed to persist index after rebuild:', err);
143→    });
144→  }, [vaultKeypair]);
145→
146→  // Register rebuild callback so FileBrowser can trigger it
147→  useEffect(() => {
148→    registerRebuildCallback(rebuildIndex);
149→    return () => {
150→      registerRebuildCallback(() => {});
151→    };
152→  }, [rebuildIndex]);
153→
154→  // Clear index (called on logout)
155→  const clearIndex = useCallback(async () => {
156→    try {
157→      await searchIndexService.clear();
158→    } catch (err) {
159→      console.warn('[search] Failed to clear index:', err);
160→    }
161→    setIsIndexReady(false);
162→    hasLoadedFromDb.current = false;
163→    setIsOpen(false);
164→    setQuery('');
165→    setResults([]);
166→  }, []);
167→
168→  // Auto-clear on logout: when isAuthenticated transitions true -> false
169→  useEffect(() => {
170→    if (prevAuth.current && !isAuthenticated) {
171→      clearIndex();
172→    }
173→    prevAuth.current = isAuthenticated;
174→  }, [isAuthenticated, clearIndex]);
175→
176→  return {
177→    isOpen,
178→    query,
179→    setQuery,
180→    results,
181→    isIndexReady,
182→    isBuilding,
183→    open,
184→    close,
185→    toggle,
186→    rebuildIndex,
187→    clearIndex,
188→    resultCount: results.length,
189→  };
190→}
191→
192→export type { SearchResult };
193→

