  1→import { ReactNode, useCallback } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { StagingBanner } from '../StagingBanner';
  4→import { MatrixBackground } from '../MatrixBackground';
  5→import { useAnyModalOpen } from '../../hooks/useModalOpen';
  6→import { useSearch } from '../../hooks/useSearch';
  7→import { AppHeader } from './AppHeader';
  8→import { AppSidebar } from './AppSidebar';
  9→import { AppFooter } from './AppFooter';
 10→import { SearchPalette } from '../file-browser/SearchPalette';
 11→import { DeviceApprovalModal } from '../mfa/DeviceApprovalModal';
 12→import { MfaEnrollmentPrompt } from '../mfa/MfaEnrollmentPrompt';
 13→import type { SearchResult } from '../../services/search-index.service';
 14→import '../../styles/layout.css';
 15→
 16→interface AppShellProps {
 17→  children: ReactNode;
 18→}
 19→
 20→/**
 21→ * App shell layout component.
 22→ * Provides the fixed layout structure with header, sidebar, footer,
 23→ * and a scrollable main content area.
 24→ *
 25→ * Also mounts cross-device approval modal, MFA enrollment prompt,
 26→ * and search palette overlay so they appear regardless of which
 27→ * authenticated page the user is on.
 28→ */
 29→export function AppShell({ children }: AppShellProps) {
 30→  const isStaging = import.meta.env.VITE_ENVIRONMENT === 'staging';
 31→  const anyModalOpen = useAnyModalOpen();
 32→  const search = useSearch();
 33→  const navigate = useNavigate();
 34→
 35→  const handleSelectResult = useCallback(
 36→    (result: SearchResult) => {
 37→      search.close();
 38→      if (result.parentFolderId === 'root') {
 39→        navigate('/files');
 40→      } else {
 41→        navigate(`/files/${result.parentFolderId}`);
 42→      }
 43→    },
 44→    [search, navigate]
 45→  );
 46→
 47→  if (isStaging) {
 48→    return (
 49→      <div
 50→        style={{ display: 'flex', flexDirection: 'column', height: '100vh', overflow: 'hidden' }}
 51→      >
 52→        <StagingBanner variant="compact" />
 53→        <div className="app-shell" data-testid="app-shell" style={{ height: 'auto', flex: 1 }}>
 54→          <MatrixBackground paused={anyModalOpen} frameInterval={50} />
 55→          <AppHeader onSearchClick={search.open} />
 56→          <MfaEnrollmentPrompt />
 57→          <AppSidebar />
 58→          <main className="app-main">{children}</main>
 59→          <AppFooter />
 60→          <DeviceApprovalModal />
 61→          <SearchPalette
 62→            isOpen={search.isOpen}
 63→            query={search.query}
 64→            onQueryChange={search.setQuery}
 65→            results={search.results}
 66→            resultCount={search.resultCount}
 67→            isBuilding={search.isBuilding}
 68→            isIndexReady={search.isIndexReady}
 69→            onClose={search.close}
 70→            onSelectResult={handleSelectResult}
 71→          />
 72→        </div>
 73→      </div>
 74→    );
 75→  }
 76→
 77→  return (
 78→    <div className="app-shell" data-testid="app-shell">
 79→      <MatrixBackground paused={anyModalOpen} frameInterval={50} />
 80→      <AppHeader onSearchClick={search.open} />
 81→      <MfaEnrollmentPrompt />
 82→      <AppSidebar />
 83→      <main className="app-main">{children}</main>
 84→      <AppFooter />
 85→      <DeviceApprovalModal />
 86→      <SearchPalette
 87→        isOpen={search.isOpen}
 88→        query={search.query}
 89→        onQueryChange={search.setQuery}
 90→        results={search.results}
 91→        resultCount={search.resultCount}
 92→        isBuilding={search.isBuilding}
 93→        isIndexReady={search.isIndexReady}
 94→        onClose={search.close}
 95→        onSelectResult={handleSelectResult}
 96→      />
 97→    </div>
 98→  );
 99→}
