  3→/**
  4→ * Page object for FileList component interactions.
  5→ *
  6→ * Encapsulates all file and folder list interactions in the main content area.
  7→ * Uses semantic selectors (getByRole, getByText) for maintainability.
  8→ */
  9→export class FileListPage {
 10→  constructor(private readonly page: Page) {}
 11→
 12→  /**
 13→   * Get the file list container (grid role).
 14→   */
 15→  fileListContainer(): Locator {
 16→    return this.page.locator('.file-list[role="grid"]');
 17→  }
 18→
 19→  /**
 20→   * Get all file list items.
 21→   */
 22→  fileItems(): Locator {
 23→    return this.page.locator('.file-list-item');
 24→  }
 25→
 26→  /**
 27→   * Get a specific item by name (file or folder).
 28→   * Uses the item text content to locate.
 29→   */
 30→  getItem(name: string): Locator {
 31→    return this.page.locator('.file-list-item', { hasText: name }).filter({
 32→      has: this.page.locator('.file-list-item-name', { hasText: name }),
 33→    });
 34→  }
 35→
 36→  /**
 37→   * Get a specific file item by name.
 38→   * Files have size displayed (not "-").
 39→   */
 40→  getFileItem(name: string): Locator {
 41→    return this.getItem(name).filter({
 42→      hasNot: this.page.locator('.file-list-item-size', { hasText: '-' }),
 43→    });
 44→  }
 45→
 46→  /**
 47→   * Get a specific folder item by name.
 48→   * Folders have size displayed as "-".
 49→   */
 50→  getFolderItem(name: string): Locator {
 51→    return this.getItem(name).filter({
 52→      has: this.page.locator('.file-list-item-size', { hasText: '-' }),
 53→    });
 54→  }
 55→
 56→  /**
 57→   * Right-click an item to open context menu.
 58→   */
 59→  async rightClickItem(name: string): Promise<void> {
 60→    await this.getItem(name).click({ button: 'right' });
 61→  }
 62→
 63→  /**
 64→   * Double-click a folder to navigate into it.
 65→   */
 66→  async doubleClickFolder(name: string): Promise<void> {
 67→    await this.getFolderItem(name).dblclick();
 68→  }
 69→
 70→  /**
 71→   * Single click to select an item.
 72→   */
 73→  async selectItem(name: string): Promise<void> {
 74→    await this.getItem(name).click();
 75→  }
 76→
 77→  /**
 78→   * Get the total count of visible items.
 79→   */
 80→  async getItemCount(): Promise<number> {
 81→    return await this.fileItems().count();
 82→  }
 83→
 84→  /**
 85→   * Check if an item is visible in the list.
 86→   */
 87→  async isItemVisible(name: string): Promise<boolean> {
 88→    return await this.getItem(name).isVisible();
 89→  }
 90→
 91→  /**
 92→   * Wait for an item to appear in the list.
 93→   * Useful after file upload or folder creation.
 94→   */
 95→  async waitForItemToAppear(name: string, options?: { timeout?: number }): Promise<void> {
 96→    await this.getItem(name).waitFor({ state: 'visible', ...options });
 97→  }
 98→
 99→  /**
100→   * Wait for an item to disappear from the list.
101→   * Useful after deletion or move.
102→   */
103→  async waitForItemToDisappear(name: string, options?: { timeout?: number }): Promise<void> {
104→    await this.getItem(name).waitFor({ state: 'hidden', ...options });
105→  }
106→
107→  /**
108→   * Check if an item is currently selected.
109→   */
110→  async isItemSelected(name: string): Promise<boolean> {
111→    const item = this.getItem(name);
112→    const className = await item.getAttribute('class');
113→    return className?.includes('file-list-item--selected') ?? false;
114→  }
115→
116→  /**
117→   * Get the size displayed for a file item.
118→   */
119→  async getFileSize(name: string): Promise<string> {
120→    const item = this.getFileItem(name);
121→    return (await item.locator('.file-list-item-size').textContent()) ?? '';
122→  }
123→
124→  /**
125→   * Get the modified date displayed for an item.
126→   */
127→  async getModifiedDate(name: string): Promise<string> {
128→    const item = this.getItem(name);
129→    return (await item.locator('.file-list-item-date').textContent()) ?? '';
130→  }
131→
132→  /**
133→   * Get all visible item names in order.
134→   * Useful for verifying sort order.
135→   */
136→  async getVisibleItemNames(): Promise<string[]> {
137→    const items = this.fileItems();
138→    const count = await items.count();
139→    const names: string[] = [];
140→
141→    for (let i = 0; i < count; i++) {
142→      const nameText = await items.nth(i).locator('.file-list-item-name').textContent();
143→      if (nameText) {
144→        names.push(nameText);
145→      }
146→    }
147→
148→    return names;
149→  }
150→
151→  /**
152→   * Get item type (file or folder) by examining the size field.
153→   * Folders show "-" for size, files show actual size.
154→   */
155→  async getItemType(name: string): Promise<'file' | 'folder'> {
156→    const item = this.getItem(name);
157→    const sizeText = await item.locator('.file-list-item-size').textContent();
158→    // Folders show "-" for size, files show actual size
159→    return sizeText?.trim() === '-' ? 'folder' : 'file';
160→  }
161→
162→  /**
163→   * Get the internal item ID from the DOM data-item-id attribute.
164→   * This is the actual UUID used by the application, not the display name.
165→   *
166→   * @param name - Display name of the item
167→   * @returns The internal UUID of the item
168→   * @throws Error if item not found or doesn't have an ID
169→   */
170→  async getItemId(name: string): Promise<string> {
171→    const item = this.getItem(name);
172→    const itemId = await item.getAttribute('data-item-id');
173→    if (!itemId) {
174→      throw new Error(`Could not find item ID for "${name}"`);
175→    }
176→    return itemId;
177→  }
178→
179→  /**
180→   * Perform a drag-drop move operation from the file list to a folder.
181→   * Uses Playwright's built-in drag and drop.
182→   *
183→   * @param itemName - Name of the item to drag
184→   * @param targetLocator - Locator for the drop target
185→   */
186→  async dragItemTo(
187→    itemName: string,
188→    targetLocator: import('@playwright/test').Locator
189→  ): Promise<void> {
190→    const sourceItem = this.getItem(itemName);
191→    await sourceItem.dragTo(targetLocator);
192→  }
193→
194→  /**
195→   * Drag an item to a folder row in the file list.
196→   * This performs a drag-and-drop from one file list item to a folder row.
197→   *
198→   * @param itemName - Name of the item to drag
199→   * @param folderName - Name of the destination folder in the list
200→   */
201→  async dragToFolder(itemName: string, folderName: string): Promise<void> {
202→    const sourceItem = this.getItem(itemName);
203→    const targetFolder = this.getFolderItem(folderName);
204→    await sourceItem.dragTo(targetFolder);
205→  }
206→
207→  // ========================================
208→  // Multi-selection methods
209→  // ========================================
210→
211→  /**
212→   * Ctrl+click (Meta on macOS) an item to toggle its selection.
213→   */
214→  async ctrlClickItem(name: string): Promise<void> {
215→    await this.getItem(name).click({ modifiers: ['ControlOrMeta'] });
216→  }
217→
218→  /**
219→   * Shift+click an item for range selection.
220→   */
221→  async shiftClickItem(name: string): Promise<void> {
222→    await this.getItem(name).click({ modifiers: ['Shift'] });
223→  }
224→
225→  /**
226→   * Click the checkbox on an item row.
227→   * Checkboxes appear on hover or when multi-select is active.
228→   */
229→  async clickCheckbox(name: string): Promise<void> {
230→    const item = this.getItem(name);
231→    const checkbox = item.locator('.file-list-item-checkbox');
232→    await checkbox.click();
233→  }
234→
235→  /**
236→   * Click the header (select-all) checkbox.
237→   */
238→  async clickHeaderCheckbox(): Promise<void> {
239→    await this.page.locator('.file-list-header-checkbox').click();
240→  }
241→
242→  /**
243→   * Check if the header checkbox is checked.
244→   */
245→  async isHeaderCheckboxChecked(): Promise<boolean> {
246→    const ariaChecked = await this.page
247→      .locator('.file-list-header-checkbox')
248→      .getAttribute('aria-checked');
249→    return ariaChecked === 'true';
250→  }
251→
252→  /**
253→   * Get names of all currently selected items.
254→   */
255→  async getSelectedItemNames(): Promise<string[]> {
256→    const selected = this.page.locator('.file-list-item--selected .file-list-item-name');
257→    const count = await selected.count();
258→    const names: string[] = [];
259→    for (let i = 0; i < count; i++) {
260→      const text = await selected.nth(i).textContent();
261→      if (text) names.push(text);
262→    }
263→    return names;
264→  }
265→
266→  /**
267→   * Get the count of currently selected items.
268→   */
269→  async getSelectedCount(): Promise<number> {
270→    return await this.page.locator('.file-list-item--selected').count();
271→  }
272→}
